content:
{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "وكما يفعلون حتى هذا اليوم بمختاري، هكذا أفعل أنا أيضاً وأجازي في حضنهم."
    ,
      "chapter": 15,
      "verse": 21
    },
    {
      "text_ar": "يقول السيد الرب: يدي اليمنى لن تشفق على الخطاة، وسيفي لن يتوقف عن أولئك الذين سفكوا دماً بريئاً على الأرض."
    ,
      "chapter": 15,
      "verse": 22
    },
    {
      "text_ar": "قد خرجت نار من غضبه وأكلت أساسات الأرض والخطاة كالقش المحترق."
    ,
      "chapter": 15,
      "verse": 23
    },
    {
      "text_ar": "ويل للذين يخطئون ولا يحفظون وصاياي! يقول الرب."
    ,
      "chapter": 15,
      "verse": 24
    },
    {
      "text_ar": "لن أفقدهم الشفقة. اذهبوا في طريقكم أيها الأولاد المتمردون! لا تدنسوا مقدسي!"
    ,
      "chapter": 15,
      "verse": 25
    },
    {
      "text_ar": "لأن الرب يعرف جميع الذين يتعدون عليه، لذلك سيسلمهم إلى الموت والهلاك."
    ,
      "chapter": 15,
      "verse": 26
    },
    {
      "text_ar": "لأنه الآن قد أتت الشرور على الأرض كلها، وستبقون فيها؛ لأن الله لن ينجيكم، لأنكم أخطأتم إليه."
    ,
      "chapter": 15,
      "verse": 27
    },
    {
      "text_ar": "هوذا منظر مرعب يظهر من الشرق!"
    ,
      "chapter": 15,
      "verse": 28
    },
    {
      "text_ar": "ستخرج شعوب تنانين العربية بمركبات كثيرة. ومنذ اليوم الذي انطلقوا فيه، يُحمل فحيحهم فوق الأرض، حتى يخاف ويرتعد أيضاً كل الذين يسمعونهم."
    ,
      "chapter": 15,
      "verse": 29
    },
    {
      "text_ar": "وأيضاً الكارمونيون، الهائجون بغضب، سيخرجون مثل خنازير البر الوحشية. سيأتون بقوة عظيمة ويشتبكون معهم في الحرب، وسيخربون قسماً من أرض الآشوريين بأسنانهم."
    ,
      "chapter": 15,
      "verse": 30
    },
    {
      "text_ar": "حينئذ تكون الغلبة للتنانين متذكرين طبيعتهم. وإذا تحولوا متآمرين معاً بقوة عظيمة لاضطهادهم،"
    ,
      "chapter": 15,
      "verse": 31
    },
    {
      "text_ar": "حينئذ يضطرب هؤلاء ويصمتون بقوتهم، ويدورون ويهربون."
    ,
      "chapter": 15,
      "verse": 32
    },
    {
      "text_ar": "ومن أرض الآشوريين، سيهاجمهم عدو يكمن ويهلك واحداً منهم. وسيكون على جيشهم خوف ورتربة، وتردد على ملوكهم."
    ,
      "chapter": 15,
      "verse": 33
    },
    {
      "text_ar": "هوذا سحب من الشرق، ومن الشمال إلى الجنوب! إنها مرعبة جداً في منظرها، ومملوءة غضباً وعاصفة."
    ,
      "chapter": 15,
      "verse": 34
    },
    {
      "text_ar": "ستصطدم الواحدة بالأخرى. وستصب عاصفة ثقيلة على الأرض، بل عاصفتها الخاصة. وسيكون هناك دم من السيف حتى بطن الحصان،"
    ,
      "chapter": 15,
      "verse": 35
    },
    {
      "text_ar": "وحتى فخذ الإنسان، وحتى عرقوب الجمل."
    ,
      "chapter": 15,
      "verse": 36
    },
    {
      "text_ar": "سيكون خوف ورعدة عظيمة على الأرض. والذين يرون ذلك الغضب سيخافون، وستمسك بهم الرعدة."
    ,
      "chapter": 15,
      "verse": 37
    },
    {
      "text_ar": "بعد هذا، ستثار عواصف عظيمة من الجنوب، ومن الشمال، وجزء آخر من الغرب."
    ,
      "chapter": 15,
      "verse": 38
    },
    {
      "text_ar": "وستقوم رياح قوية من الشرق وتغلق عليها، حتى السحابة التي أقامها بغضب؛ والعاصفة التي كان مفروضاً أن تحدث الدمار بريح الشرق ستندفع بعنف نحو الجنوب والغرب."
    ,
      "chapter": 15,
      "verse": 39
    },
    {
      "text_ar": "وسترتفع سحب عظيمة وقوية، مملوءة غضباً، مع العاصفة، لكي تهلك الأرض كلها والساكنين فيها. وستصب فوق كل شامخ وعال عاصفة رهيبة،"
    ,
      "chapter": 15,
      "verse": 40
    }
  ]
}
